CREATE VIEW "DEPT_EMPLOYEE_COUNT" AS SELECT D.ID AS DEPT_ID, D.NAME AS DEPT_NAME, COUNT(E.ID) AS EMP_COUNT
FROM DEPARTMENTS D
LEFT JOIN EMPLOYEES E ON D.ID = E.DEPARTMENT_ID
GROUP BY D.ID, D.NAME;
CREATE MATERIALIZED VIEW "MV_DEPT_STATS" AS SELECT 
    D.ID AS DEPT_ID,
    D.NAME AS DEPT_NAME,
    COUNT(E.ID) AS TOTAL_EMPLOYEES,
    NVL(SUM(E.SALARY), 0) AS TOTAL_PAYROLL,
    NVL(AVG(E.SALARY), 0) AS AVG_SALARY,
    NVL(MAX(E.SALARY), 0) AS MAX_SALARY,
    NVL(MIN(E.SALARY), 0) AS MIN_SALARY
FROM DEPARTMENTS D
LEFT JOIN EMPLOYEES E ON D.ID = E.DEPARTMENT_ID
GROUP BY D.ID, D.NAME
;
COMMENT ON MATERIALIZED VIEW "MV_DEPT_STATS" IS 'snapshot table for snapshot TESTSCHEMA.MV_DEPT_STATS';
CREATE VIEW "DEPT_SUMMARY" AS SELECT 
    DEC.DEPT_ID,
    DEC.DEPT_NAME,
    DEC.EMP_COUNT,
    NVL(AVG(E.SALARY), 0) AS AVG_SALARY
FROM DEPT_EMPLOYEE_COUNT DEC
LEFT JOIN EMPLOYEES E ON DEC.DEPT_ID = E.DEPARTMENT_ID
GROUP BY DEC.DEPT_ID, DEC.DEPT_NAME, DEC.EMP_COUNT;
CREATE VIEW "DEPT_MANAGER_SUMMARY" AS SELECT 
    DS.DEPT_ID,
    DS.DEPT_NAME,
    DS.EMP_COUNT,
    DS.AVG_SALARY,
    M.NAME AS MANAGER_NAME
FROM DEPT_SUMMARY DS
JOIN DEPARTMENTS D ON DS.DEPT_ID = D.ID
LEFT JOIN EMPLOYEES M ON D.MANAGER_ID = M.ID;
COMMENT ON MATERIALIZED VIEW "MV_DEPT_STATS" IS 'snapshot table for snapshot TESTSCHEMA.MV_DEPT_STATS';
